CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS administrators(user_id INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fsm(key TEXT PRIMARY KEY, state TEXT, data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS drafts(id TEXT PRIMARY KEY, owner_id INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'DRAFT', payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bindings(draft_id TEXT PRIMARY KEY REFERENCES drafts(id), remote_id TEXT UNIQUE NOT NULL, test_only INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, item_id TEXT NOT NULL, status TEXT NOT NULL, chat_id TEXT, amount TEXT, created_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_created ON orders(created_at);
CREATE TABLE IF NOT EXISTS inventory(id INTEGER PRIMARY KEY, item_id TEXT NOT NULL, secret TEXT NOT NULL, fingerprint TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','RESERVED','DELIVERED','QUARANTINED')), UNIQUE(item_id,fingerprint));
CREATE INDEX IF NOT EXISTS inventory_available ON inventory(item_id,status);
CREATE TABLE IF NOT EXISTS reservations(order_id TEXT PRIMARY KEY REFERENCES orders(id), inventory_id INTEGER UNIQUE NOT NULL REFERENCES inventory(id));
CREATE TABLE IF NOT EXISTS inbox(key TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, received_at TEXT NOT NULL, processed_at TEXT);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, operation_key TEXT UNIQUE NOT NULL, kind TEXT NOT NULL, target TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSING','SUCCEEDED','RETRYABLE_FAILED','UNCERTAIN','PERMANENT_FAILED')), lease_until REAL, lease_token TEXT, attempts INTEGER NOT NULL DEFAULT 0, result TEXT, error_code TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS outbox_ready ON outbox(status,created_at);
CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, created_at TEXT, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_chat ON chat_messages(chat_id,created_at);
CREATE TABLE IF NOT EXISTS notifications(event_key TEXT NOT NULL, owner_id INTEGER NOT NULL, telegram_message_id INTEGER, status TEXT NOT NULL DEFAULT 'PENDING', PRIMARY KEY(event_key,owner_id));
CREATE TABLE IF NOT EXISTS financial_operations(id TEXT PRIMARY KEY, kind TEXT NOT NULL, amount TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'RUB', created_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS promotion_expenses(operation_key TEXT PRIMARY KEY, item_id TEXT NOT NULL, amount TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_cursors(key TEXT PRIMARY KEY, cursor TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY, actor INTEGER, action TEXT NOT NULL, target TEXT NOT NULL, outcome TEXT NOT NULL, created_at TEXT NOT NULL);
